  @override
  void initState() {
    super.initState();
    _initFolders();
    _loadSutras();
    _loadLastRead();
    _loadAssetManifest();
    _searchController.addListener(_filterSutras);
    _drawerController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 320),
    );
    final drawerCurve = CurvedAnimation(
      parent: _drawerController,
      curve: Curves.easeOutCubic,
      reverseCurve: Curves.easeInCubic,
    );
    _drawerSlide =
        Tween<Offset>(begin: const Offset(-1, 0), end: Offset.zero).animate(drawerCurve);
    _overlayOpacity = Tween<double>(begin: 0, end: 1).animate(drawerCurve);
  }

  @override
  void dispose() {
    _drawerController.dispose();
    _searchController.dispose();
    super.dispose();
  }

  List<String> _folders = [];

  void _initFolders() {
    _folders = _folderDisplayNames.values.toList();
    for (String folder in _folders) {
      _folderExpanded[folder] = false; // 所有子文件夹都是折叠状态
    }
  }

  Future<void> _loadSutras() async {
    final prefs = await SharedPreferences.getInstance();
    List<String>? sutraJsonList = prefs.getStringList('sutras');

    if (sutraJsonList != null && sutraJsonList.isNotEmpty) {
      // 如果检测到 APK 被“覆盖安装/更新”，把缺失的默认经书补回（保证重装后被清空的子文件夹可恢复）。
      final shouldRestoreDefaults = await _shouldRestoreDefaultsAfterApkUpdate(prefs);
      if (shouldRestoreDefaults) {
        final loaded = sutraJsonList
            .map((jsonStr) => Sutra.fromJson(jsonDecode(jsonStr)))
            .toList();
        final restored = _mergeMissingDefaultSutras(loaded);
        sutraJsonList = restored.map((s) => jsonEncode(s.toJson())).toList();
        await prefs.setStringList('sutras', sutraJsonList);
      }

      final effectiveList = sutraJsonList;
      setState(() {
        _allSutras = effectiveList
            .map((jsonStr) => Sutra.fromJson(jsonDecode(jsonStr)))
            .toList();
        _filteredSutras = List.from(_allSutras);
      });
      _bestAssetPathByTitleCache.clear();
      _missingComputed = false;
      _recomputeMissingSutrasIfReady();
    } else {
      setState(() {
        _allSutras = List.from(_defaultSutras);
        _filteredSutras = List.from(_allSutras);
      });
      _saveSutras();
      // 初始化安装标记（避免第一次启动就触发“恢复默认”）。
      await _shouldRestoreDefaultsAfterApkUpdate(prefs);
      _bestAssetPathByTitleCache.clear();
      _missingComputed = false;
      _recomputeMissingSutrasIfReady();
    }
  }

  Future<bool> _shouldRestoreDefaultsAfterApkUpdate(SharedPreferences prefs) async {
    if (kIsWeb) return false;
    if (!Platform.isAndroid) return false;
    try {
      final current = await _appChannel.invokeMethod<int>('getLastUpdateTime');
      if (current == null) return false;
      final last = prefs.getInt(_kApkLastUpdateTimeKey);
      if (last == null) {
        await prefs.setInt(_kApkLastUpdateTimeKey, current);
        return false;
      }
      if (last != current) {
        await prefs.setInt(_kApkLastUpdateTimeKey, current);
        return true;
      }
    } catch (_) {
      // ignore
    }
    return false;
  }

  List<Sutra> _mergeMissingDefaultSutras(List<Sutra> current) {
    // 用 filePath 作为唯一键：默认经书都来自 assets 路径；用户导入一般是本地路径。
    final existingPaths = <String>{};
    for (final s in current) {
      final p = s.filePath;
      if (p != null && p.isNotEmpty) existingPaths.add(p);
    }

    final merged = List<Sutra>.from(current);
    for (final d in _defaultSutras) {
      final p = d.filePath;
      if (p != null && p.isNotEmpty && !existingPaths.contains(p)) {
        merged.add(d);
      }
    }
    return merged;
  }

  Future<void> _saveSutras() async {
    SharedPreferences prefs = await SharedPreferences.getInstance();
    List<String> sutraJsonList = _allSutras.map((sutra) => jsonEncode(sutra.toJson())).toList();
    await prefs.setStringList('sutras', sutraJsonList);
  }

  void _filterSutras() {
    setState(() {
      if (_searchController.text.isEmpty) {
        // 搜索内容为空时，恢复默认排序和默认文件夹展开状态
        _allSutras.sort((a, b) {
          if (a.isPinned && !b.isPinned) return -1;
          if (!a.isPinned && b.isPinned) return 1;
          return 0;
        });
         _filteredSutras = List.from(_allSutras);
      } else {
        // 有搜索内容时，过滤经文并管理文件夹展开状态
        var filtered = _allSutras
            .where((sutra) =>
                sutra.title.contains(_searchController.text))
            .toList();
        filtered.sort((a, b) {
          if (a.isPinned && !b.isPinned) return -1;
          if (!a.isPinned && b.isPinned) return 1;
          return 0;
        });
        _filteredSutras = filtered;

        // 管理文件夹展开状态：只展开包含搜索结果的文件夹
        _manageFolderExpansionForSearch();
      }
    });
  }

  void _manageFolderExpansionForSearch() {
    // 找到所有包含搜索结果的文件夹
    Set<String> foldersWithResults = {};
    for (var sutra in _filteredSutras) {
      if (sutra.folder != null) {
        foldersWithResults.add(sutra.folder!);
      }
    }

    // 更新文件夹展开状态
    for (var folder in _folders) {
      _folderExpanded[folder] = foldersWithResults.contains(folder);
    }

    // 如果有收藏夹中的经文匹配，也展开收藏夹
    bool hasFavoriteResults = _filteredSutras.any((sutra) => sutra.isFavorite);
    if (hasFavoriteResults) {
      _isFavoriteExpanded = true;
    }

    // 如果有已读经文匹配，也展开已读文件夹
    bool hasReadResults = _filteredSutras.any((sutra) => sutra.isRead);
    if (hasReadResults) {
      _isReadExpanded = true;
    }
  }

