  Widget _buildDailySutraCard() {
    final rec = _todayRecommendation;
    final sutra = _findSutra(rec['key']!);
    if (sutra == null) return const SizedBox.shrink();
    final now = DateTime.now();
    return Container(
      margin: const EdgeInsets.fromLTRB(12, 8, 12, 4),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Color(0xFF5d4037), Color(0xFF7a5c4e)],
        ),
        borderRadius: BorderRadius.circular(12),
        boxShadow: [
          BoxShadow(color: const Color(0xFF5d4037).withValues(alpha: 0.2), blurRadius: 10, offset: const Offset(0, 3)),
        ],
      ),
      child: InkWell(
        borderRadius: BorderRadius.circular(12),
        onTap: () {
          _dismissKeyboard();
          _openSutra(sutra);
        },
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                const Icon(Icons.wb_sunny, color: Color(0xFFF4E6D3), size: 16),
                const SizedBox(width: 6),
                Text(
                  '今日推荐 · ${now.month}月${now.day}日',
                  style: const TextStyle(color: Color(0xFFF4E6D3), fontSize: 12),
                ),
                const Spacer(),
                const Text(
                  '开始阅读 ›',
                  style: TextStyle(color: Color(0xFFF4E6D3), fontSize: 12),
                ),
              ],
            ),
            const SizedBox(height: 10),
            Text(
              rec['name']!,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 17,
                fontWeight: FontWeight.w600,
              ),
            ),
            const SizedBox(height: 5),
            Text(
              rec['intro']!,
              style: const TextStyle(color: Color(0xFFE8D9C4), fontSize: 13, height: 1.5),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildAllSutrasFolder() {
    return Column(
      children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          color: const Color(0xFFcec6c3),
          child: Row(
            children: [
              const Icon(Icons.book, color: Color(0xFF5d4037), size: 20),
              const SizedBox(width: 8),
              Text(
                '待阅经文 (${_getAllSutras().length})',
                style: const TextStyle(
                  color: Color(0xFF5d4037),
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ),
        ),
        ..._folders.map((folder) => _buildSubFolder(folder)),
      ],
    );
  }

  Widget _buildSubFolder(String folderName) {
    final sutras = _getSutrasInFolder(folderName);
    final isExpanded = _folderExpanded[folderName] ?? true;

    return Column(
      children: [
        GestureDetector(
          onTap: () {
            setState(() {
              _folderExpanded[folderName] = !isExpanded;
            });
          },
          onLongPress: () {
            _showFolderMenu(context, folderName);
          },
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            color: Colors.white,
            child: Row(
              children: [
                const Icon(Icons.folder, color: Color(0xFFba8e82), size: 18),
                const SizedBox(width: 8),
                Text(
                  _folderDisplayNames[folderName] ?? folderName,
                  style: const TextStyle(
                    color: Color(0xFF5d4037),
                    fontSize: 14,
                    fontWeight: FontWeight.w500,
                  ),
                ),
                const Spacer(),
                Text(
                  '${sutras.length}卷',
                  style: const TextStyle(
                    color: Color(0xFF999999),
                    fontSize: 12,
                  ),
                ),
              ],
            ),
          ),
        ),
        if (isExpanded && sutras.isNotEmpty)
          Container(
            padding: const EdgeInsets.only(left: 8, right: 8, top: 0, bottom: 15),
             color: const Color(0xFFF5EDE3),
             child: Column(
               children: sutras.map((sutra) {
                 final allSutrasIndex = _filteredSutras.indexOf(sutra);
                 return Container(
                   margin: const EdgeInsets.only(bottom: 3),
                  height: 30,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Center(
                    child: ListTile(
                      contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 0),
                      minVerticalPadding: 0,
                      dense: true,
                      title: Text(
                        sutra.title,
                        style: const TextStyle(
                          fontSize: 14,
                          height: 1,
                          color: Color(0xFF616161),
                        ),
                        overflow: TextOverflow.ellipsis,
                        maxLines: 1,
                      ),
                      onTap: () {
                        _dismissKeyboard();
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (context) => ReadingPage(
                              title: sutra.title,
                              filePath: _filePathForReading(sutra),
                            ),
                          ),
                        );
                      },
                      onLongPress: () => _showBottomSheet(context, allSutrasIndex),
                    ),
                  ),
                );
              }).toList(),
            ),
          ),
        if (isExpanded && sutras.isEmpty)
          Container(
            padding: const EdgeInsets.symmetric(vertical: 20),
            color: const Color(0xFFfafafa),
            child: Center(
              child: Text(
                '暂无内容',
                style: TextStyle(
                  color: const Color(0xFF999999),
                  fontSize: 12,
                ),
              ),
            ),
          ),
      ],
    );
  }

  Widget _buildFolder({
    required String title,
    required List<Sutra> sutras,
    required bool isExpanded,
    required VoidCallback onToggle,
    required IconData icon,
  }) {
    return Column(
      children: [
        GestureDetector(
          onTap: onToggle,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            color: const Color(0xFFcec6c3),
            child: Row(
              children: [
                Icon(icon, color: const Color(0xFF5d4037), size: 20),
                const SizedBox(width: 8),
                Text(
                  '$title (${sutras.length})',
                  style: const TextStyle(
                    color: Color(0xFF5d4037),
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const Spacer(),
                Icon(
                  isExpanded ? Icons.keyboard_arrow_up : Icons.keyboard_arrow_down,
                  color: const Color(0xFF999999),
                  size: 20,
                ),
              ],
            ),
          ),
        ),
        if (isExpanded && sutras.isNotEmpty)
          Container(
            padding: const EdgeInsets.only(left: 8, right: 8, top: 0, bottom: 15),
            child: Column(
              children: sutras.map((sutra) {
                final allSutrasIndex = _filteredSutras.indexOf(sutra);
                return Container(
                  margin: const EdgeInsets.only(bottom: 0),
                  height: 30,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Center(
                    child: ListTile(
                      contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 0),
                      minVerticalPadding: 0,
                      dense: true,
                      title: Text(
                        sutra.title,
                        style: const TextStyle(
                          fontSize: 14,
                          height: 1,
                          color: Color(0xFF616161),
                        ),
                        overflow: TextOverflow.ellipsis,
                        maxLines: 1,
                      ),
                      onTap: () {
                        _dismissKeyboard();
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (context) => ReadingPage(
                              title: sutra.title,
                              filePath: _filePathForReading(sutra),
                            ),
                          ),
                        );
                      },
                      onLongPress: () => _showBottomSheet(context, allSutrasIndex),
                    ),
                  ),
                );
              }).toList(),
            ),
          ),
        if (isExpanded && sutras.isEmpty)
          Container(
            padding: const EdgeInsets.symmetric(vertical: 20),
            child: Center(
              child: Text(
                '暂无内容',
                style: TextStyle(
                  color: const Color(0xFF999999),
                  fontSize: 12,
                ),
              ),
            ),
          ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final drawerWidth = MediaQuery.of(context).size.width * 0.82;
    return Stack(
      children: [
        Scaffold(
          backgroundColor: const Color(0xFFF5EDE3),
          appBar: AppBar(
            backgroundColor: const Color(0xFFF5EDE3),
            elevation: 0,
            shadowColor: Colors.transparent,
            iconTheme: const IconThemeData(color: Color(0xFF212121)),
            leading: IconButton(
              icon: const Icon(Icons.menu, color: Color(0xFF5d4037), size: 22),
              tooltip: '经藏',
              onPressed: _toggleDrawer,
            ),
            title: const Text(
              '诸行无常，一切皆苦；诸法无我，寂灭为乐。',
              style: TextStyle(
                color: Color(0xFF616161),
                fontSize: 12,
                fontWeight: FontWeight.normal,
              ),
              softWrap: false,
              overflow: TextOverflow.visible,
            ),
            actions: [
              Padding(
                padding: const EdgeInsets.only(right: 16),
                child: Text(
                  '${(_allSutras.where((s) => s.isRead).length / 8982 * 100).toStringAsFixed(1)}%',
                  style: const TextStyle(
                    color: Color(0xFF616161),
                    fontSize: 12,
                  ),
                ),
              ),
            ],
          ),
          body: SingleChildScrollView(
            padding: const EdgeInsets.only(bottom: 40),
            child: Column(
              children: [
                _buildRecentReadCard(),
                _buildDailySutraCard(),
              ],
            ),
          ),
        ),
        Positioned.fill(
          child: IgnorePointer(
            ignoring: !_drawerOpen,
            child: FadeTransition(
              opacity: _overlayOpacity,
              child: GestureDetector(
                onTap: _closeDrawer,
                child: const ColoredBox(color: Colors.black38),
              ),
            ),
          ),
        ),
        Positioned(
          top: 0,
          bottom: 0,
          width: drawerWidth,
          child: SlideTransition(
            position: _drawerSlide,
            child: _buildDrawerPanel(),
          ),
        ),
      ],
    );
  }

  void _toggleDrawer() {
    if (_drawerOpen) {
      _closeDrawer();
    } else {
      _openDrawer();
    }
  }

  void _openDrawer() {
    if (_searchController.text.isNotEmpty) {
      _searchController.clear();
    }
    setState(() {
      _drawerOpen = true;
      for (final folder in _folders) {
        _folderExpanded[folder] = false;
      }
    });
    _drawerController.forward();
  }

  void _closeDrawer() {
    FocusScope.of(context).unfocus();
    _drawerController.reverse();
    setState(() {
      _drawerOpen = false;
      _isFavoriteExpanded = false;
      _isReadExpanded = false;
    });
  }

  Widget _buildDrawerPanel() {
    return Material(
      color: Colors.white,
      elevation: 16,
      borderRadius: const BorderRadius.horizontal(right: Radius.circular(20)),
      clipBehavior: Clip.antiAlias,
      child: SafeArea(
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 14, 12, 4),
              child: Container(
                height: 38,
                decoration: BoxDecoration(
                  color: const Color(0xFFf8f8f8),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: TextField(
                  controller: _searchController,
                  textAlignVertical: TextAlignVertical.center,
                  decoration: const InputDecoration(
                    hintText: '搜索经文',
                    hintStyle: TextStyle(color: Color(0xFFB8B8B8), fontSize: 13),
                    prefixIcon: Padding(
                      padding: EdgeInsets.only(left: 8, right: 4),
                      child: Icon(Icons.search, color: Color(0xFF616161), size: 18),
                    ),
                    border: InputBorder.none,
                    isDense: true,
                    contentPadding: EdgeInsets.symmetric(horizontal: 12),
                  ),
                  style: const TextStyle(color: Color(0xFF212121), fontSize: 14),
                ),
              ),
            ),
            Expanded(
              child: ListView(
                padding: EdgeInsets.zero,
                children: [
                  _buildFolder(
                    title: '我的收藏',
                    sutras: _getFavoriteSutras(),
                    isExpanded: _isFavoriteExpanded,
                    onToggle: () {
                      setState(() {
                        _isFavoriteExpanded = !_isFavoriteExpanded;
                      });
                    },
                    icon: Icons.favorite,
                  ),
                  _buildFolder(
                    title: '已阅经文',
                    sutras: _getReadSutras(),
                    isExpanded: _isReadExpanded,
                    onToggle: () {
                      setState(() {
                        _isReadExpanded = !_isReadExpanded;
                      });
                    },
                    icon: Icons.check_circle,
                  ),
                  _buildAllSutrasFolder(),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
